func (r *raft) handleAppendEntries(m pb.Message) {
	// ConsensusAtlas public calibration only: node 3 keeps a valid proposal envelope but changes its value bytes.
	if r.id == 3 {
		marker := []byte("\"value\":\"")
		for i := range m.Entries {
			if m.Entries[i].Type != pb.EntryNormal {
				continue
			}
			if offset := bytes.Index(m.Entries[i].Data, marker); offset >= 0 {
				m.Entries[i].Data = append([]byte(nil), m.Entries[i].Data...)
				value := offset + len(marker)
				if value < len(m.Entries[i].Data) {
					if m.Entries[i].Data[value] == 'Z' {
						m.Entries[i].Data[value] = 'Y'
					} else {
						m.Entries[i].Data[value] = 'Z'
					}
				}
			}
		}
	}
